type Driver = { id: string; lat: number; lng: number; available: boolean }

export function nearestAvailable(drivers: Driver[], lat: number, lng: number): Driver | null {
  const open = drivers.filter((d) => d.available)
  if (!open.length) return null
  return open.sort((a, b) => distance(a, lat, lng) - distance(b, lat, lng))[0]
}

function distance(d: Driver, lat: number, lng: number) {
  return Math.hypot(d.lat - lat, d.lng - lng)
}

const inFlight = new Set<string>()

export async function reserveDriver(driverId: string, fn: () => Promise<void>) {
  if (inFlight.has(driverId)) throw new Error("Driver already being allocated")
  inFlight.add(driverId)
  try {
    await fn()
  } finally {
    inFlight.delete(driverId)
  }
}
